event.content:
{
  "name": "ticket_close",
  "description": "Close a ticket",
  "arguments": {
    "type": "object",
    "properties": {
      "files": {
        "description": "Files to include",
        "items": {
          "type": "string"
        },
        "type": "array"
      },
      "no_github": {
        "description": "Skip GitHub issue creation",
        "type": "boolean"
      },
      "path": {
        "description": "Ticket path",
        "type": "string"
      },
      "summary": {
        "description": "Summary of the ticket work",
        "type": "string"
      },
      "title": {
        "description": "New title for the ticket (also updates GitHub issue)",
        "type": "string"
      }
    },
    "required": []
  }
}
